document.addEventListener("keydown",e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==="k"){e.preventDefault();$("#search-input").focus()}});const hash=location.hash.match(/prompt-(\d+)/);localize();if(hash)openEditor(+hash[1]);

blankPrompt=function(p){return buildPrompt(p,{field:"[ҒЫЛЫМИ САЛА]",topic:"[ТАҚЫРЫП НЕМЕСЕ МІНДЕТ]",goal:"[НЕГІЗГІ МАҚСАТ]",region:"[ЕЛ НЕМЕСЕ АЙМАҚ]",group:"[АУДИТОРИЯ]",method:"[ӘДІС НЕМЕСЕ ТӘСІЛ]",language:"[ЖАУАП ТІЛІ]",length:"[ЖАУАП КӨЛЕМІ]",format:"[НӘТИЖЕ ФОРМАТЫ]",academic:"[АКАДЕМИЯЛЫҚ ДЕҢГЕЙ]"},"short")}
buildPrompt=function(p,v,mode=state.mode){
  const s=state.lang,direction=tr(directionNames[p.direction]);
  const role=s==="kk"?`Сен ${v.field} саласындағы тәжірибелі академиялық AI ассистентісің.`:s==="ru"?`Ты — опытный академический AI-ассистент в области «${v.field}».`:`You are an experienced academic AI assistant in ${v.field}.`;
  const context=s==="kk"?`Жұмыс бағыты: ${direction}\nТақырып немесе міндет: ${v.topic}\nНегізгі мақсат: ${v.goal}\nЕл немесе аймақ: ${v.region}\nАудитория: ${v.group}\nӘдіс немесе тәсіл: ${v.method}\nАкадемиялық деңгей: ${v.academic}`:s==="ru"?`Направление: ${direction}\nТема или задача: ${v.topic}\nЦель: ${v.goal}\nСтрана или регион: ${v.region}\nАудитория: ${v.group}\nМетод или подход: ${v.method}\nУровень: ${v.academic}`:`Direction: ${direction}\nTopic or task: ${v.topic}\nPrimary goal: ${v.goal}\nCountry or region: ${v.region}\nAudience: ${v.group}\nMethod or approach: ${v.method}\nAcademic level: ${v.academic}`;
  const output=s==="kk"?`Жауапты ${v.language} тілінде, ${v.format} форматында, көлемі ${v.length} етіп бер.`:s==="ru"?`Ответ дай на языке «${v.language}» в формате «${v.format}», объём: ${v.length}.`:`Respond in ${v.language}, using ${v.format}; length: ${v.length}.`;
  const steps=mode==="extended"?(s==="kk"?"\n\nҚадамдық тәртіп:\n1. Контекстің жеткіліктілігін бағала.\n2. Талдау критерийлерін түсіндір.\n3. Нәтижені құрылымда.\n4. Шектеулер мен тексеруді қажет ететін тұстарды белгіле.\n5. Келесі әрекеттерді ұсын.":s==="ru"?"\n\nПорядок работы:\n1. Оцени полноту контекста.\n2. Объясни критерии.\n3. Структурируй результат.\n4. Отметь ограничения.\n5. Предложи следующие шаги.":"\n\nWorkflow:\n1. Assess context completeness.\n2. Explain criteria.\n3. Structure the output.\n4. Flag limitations.\n5. Recommend next steps."):"";
  const safety=s==="kk"?"Академиялық адалдықты сақта. Берілмеген фактіні, авторды, DOI, сілтемені немесе статистиканы ойдан шығарма. Сенімсіз ақпаратты ашық белгіле. Құпия деректерді сұрама.":s==="ru"?"Соблюдай академическую добросовестность. Не выдумывай факты, авторов, DOI, ссылки или статистику. Отмечай неопределённость и не запрашивай конфиденциальные данные.":"Maintain academic integrity. Do not fabricate facts, authors, DOIs, citations, or statistics. State uncertainty and do not request confidential data.";
  return `${role}\n\n${context}\n\n${tr(p.task)}\n\n${output}${steps}\n\n${safety}`;
}
