$("#direction-filter").addEventListener("change",e=>{state.direction=e.target.value;state.stage="all";state.selected=null;state.onlyFavorites=state.onlyRecent=false;$("#editor-content").classList.add("hidden");$("#editor-empty").classList.remove("hidden");$("#editor-panel").classList.remove("open");renderStages();renderCards();renderAssistant()});
